package com.spinningitems;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import org.junit.Assert;
import org.junit.Test;

public class SpinningItemsPluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(SpinningItemsPlugin.class);
        RuneLite.main(args);
    }

    @Test
    public void anglesWrapInRuneScapeUnits()
    {
        Assert.assertEquals(48, SpinningItemsPlugin.spunAngle(0, 48));
        Assert.assertEquals(16, SpinningItemsPlugin.spunAngle(2000, 64));
    }

    @Test
    public void inspectionZoomIsBoundedAndScalesWithModelSize()
    {
        Assert.assertEquals(5000, ItemInspectController.calculateZoom(1));
        Assert.assertEquals(968, ItemInspectController.calculateZoom(160));
        Assert.assertEquals(128, ItemInspectController.calculateZoom(5000));
    }

    @Test
    public void parsesCollectionLogMessagesWithFormatting()
    {
        Assert.assertEquals("Dragon pickaxe",
            CollectionLogInspectManager.parseCollectionItem(
                "New item added to your collection log: <col=ff0000>Dragon pickaxe</col>"));
        Assert.assertNull(CollectionLogInspectManager.parseCollectionItem("You receive a drop: Dragon pickaxe"));
    }

    @Test
    public void classifiesCommonInventoryCategories()
    {
        Assert.assertEquals(SpinCategory.FOOD,
            SpinningItemsPlugin.classify(new String[]{"Eat", null, null}, "Shark"));
        Assert.assertEquals(SpinCategory.POTIONS,
            SpinningItemsPlugin.classify(new String[]{"Drink", null, null}, "Prayer potion(4)"));
        Assert.assertEquals(SpinCategory.WEAPONS,
            SpinningItemsPlugin.classify(new String[]{"Wield", null, null}, "Dragon scimitar"));
        Assert.assertEquals(SpinCategory.ARMOUR,
            SpinningItemsPlugin.classify(new String[]{"Wear", null, null}, "Rune platebody"));
        Assert.assertEquals(SpinCategory.TOOLS,
            SpinningItemsPlugin.classify(new String[]{"Use", null, null}, "Dragon pickaxe"));
        Assert.assertEquals(SpinCategory.OTHER,
            SpinningItemsPlugin.classify(new String[]{"Use", null, null}, "Coins"));
    }

    @Test
    public void onlyNotedItemTemplatesAreExcludedFromSpinning()
    {
        Assert.assertFalse(SpinningItemsPlugin.isNoted(-1));
        Assert.assertTrue(SpinningItemsPlugin.isNoted(799));
    }
}

package com.spinningitems;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(SpinningItemsConfig.GROUP)
public interface SpinningItemsConfig extends Config
{
    String GROUP = "spinningitems";

    @ConfigItem(
        keyName = "itemInspection",
        name = "Item inspection",
        description = "Add an Inspect option when right-clicking an item"
    )
    default boolean itemInspection()
    {
        return true;
    }

    @ConfigItem(
        keyName = "requireShiftForInspect",
        name = "Require Shift for Inspect",
        description = "Only show the inventory Inspect option while Shift is held"
    )
    default boolean requireShiftForInspect()
    {
        return false;
    }

    @Range(min = 8, max = 256)
    @ConfigItem(
        keyName = "spinSpeed",
        name = "Spin speed",
        description = "How quickly hovered inventory items rotate"
    )
    default int spinSpeed()
    {
        return 48;
    }

    @ConfigItem(
        keyName = "equipmentSpinStyle",
        name = "Equipment rotation",
        description = "Choose left-to-right rotation, a forward tumble, or a mixed spin"
    )
    default EquipmentSpinStyle equipmentSpinStyle()
    {
        return EquipmentSpinStyle.HORIZONTAL_TUMBLE;
    }

    @ConfigItem(
        keyName = "spinFood",
        name = "Food",
        description = "Spin edible items such as food"
    )
    default boolean spinFood()
    {
        return true;
    }

    @ConfigItem(
        keyName = "spinPotions",
        name = "Potions and drinks",
        description = "Spin potions and other drinkable items"
    )
    default boolean spinPotions()
    {
        return true;
    }

    @ConfigItem(
        keyName = "spinArmour",
        name = "Armour and clothing",
        description = "Spin wearable armour, clothing, and jewellery"
    )
    default boolean spinArmour()
    {
        return true;
    }

    @ConfigItem(
        keyName = "spinWeapons",
        name = "Weapons",
        description = "Spin wieldable weapons"
    )
    default boolean spinWeapons()
    {
        return true;
    }

    @ConfigItem(
        keyName = "spinTools",
        name = "Tools",
        description = "Spin common skilling and utility tools"
    )
    default boolean spinTools()
    {
        return true;
    }

    @ConfigItem(
        keyName = "spinOther",
        name = "Other items",
        description = "Spin items which do not match another category"
    )
    default boolean spinOther()
    {
        return true;
    }
}

package com.spinningitems;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.SpritePixels;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.widgets.ItemQuantityMode;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Station's Inspect Details",
    description = "Spin hovered inventory items and inspect their models, stats, and collection-log unlocks",
    tags = {"inventory", "item", "model", "spin", "inspect", "collection log", "cosmetic"}
)
public class SpinningItemsPlugin extends Plugin
{
    private static final int ANGLE_MASK = 2047;
    private static final int UPDATE_INTERVAL = 2;
    private static final String[] TOOL_WORDS = {
        "axe", "pickaxe", "hammer", "chisel", "knife", "saw", "rake", "spade",
        "secateurs", "tinderbox", "pestle", "needle", "shears", "fishing rod",
        "harpoon", "lobster pot", "mortar", "watering can"
    };

    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private SpinningItemsOverlay overlay;

    @Inject
    private ItemInspectOverlay inspectOverlay;

    @Inject
    private SpinningItemsConfig config;

    @Inject
    private ItemInspectController itemInspector;

    @Inject
    private CollectionLogInspectManager collectionLogInspector;

    @Inject
    private MouseManager mouseManager;

    @Inject
    private KeyManager keyManager;

    private SpinningItemsOverlay.HoveredSlot activeSlot;
    private int spinOffset;
    private int updateCounter;

    @Provides
    SpinningItemsConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(SpinningItemsConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
        overlayManager.add(inspectOverlay);
        mouseManager.registerMouseListener(itemInspector);
        mouseManager.registerMouseWheelListener(itemInspector);
        keyManager.registerKeyListener(itemInspector);
    }

    @Override
    protected void shutDown()
    {
        keyManager.unregisterKeyListener(itemInspector);
        mouseManager.unregisterMouseWheelListener(itemInspector);
        mouseManager.unregisterMouseListener(itemInspector);
        itemInspector.close();
        collectionLogInspector.reset();
        overlayManager.remove(inspectOverlay);
        overlayManager.remove(overlay);
        clearActiveSlot();
    }

    @Subscribe
    public void onClientTick(ClientTick event)
    {
        itemInspector.update();
        collectionLogInspector.update();
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            clearActiveSlot();
            return;
        }

        if (itemInspector.isOpen())
        {
            clearActiveSlot();
            return;
        }

        SpinningItemsOverlay.HoveredSlot hovered = overlay.getHoveredSlot(client.getGameCycle());
        if (hovered == null)
        {
            clearActiveSlot();
            return;
        }

        ItemComposition composition = client.getItemDefinition(hovered.itemId);
        SpinCategory category = composition == null
            ? SpinCategory.OTHER
            : classify(composition.getInventoryActions(), composition.getName());
        if (composition == null || isNoted(composition.getNote()) || !isEnabled(category))
        {
            clearActiveSlot();
            return;
        }

        if (!hovered.equals(activeSlot))
        {
            activeSlot = hovered;
            spinOffset = 0;
            updateCounter = UPDATE_INTERVAL;
        }

        if (++updateCounter >= UPDATE_INTERVAL)
        {
            updateCounter = 0;
            spinOffset = (spinOffset + config.spinSpeed()) & ANGLE_MASK;
            renderSlot(composition, hovered, category);
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        collectionLogInspector.onChatMessage(event);
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event)
    {
        MenuEntry original = event.getMenuEntry();
        if (!config.itemInspection()
            || (config.requireShiftForInspect() && !client.isKeyPressed(KeyCode.KC_SHIFT))
            || !"Examine".equalsIgnoreCase(event.getOption()))
        {
            return;
        }

        int itemId = event.getItemId();
        if (itemId < 0)
        {
            itemId = original.getItemId();
        }
        if (itemId < 0 && original.getWidget() != null)
        {
            itemId = original.getWidget().getItemId();
        }
        if (itemId < 0)
        {
            return;
        }

        final int inspectedItemId = itemId;
        client.createMenuEntry(-1)
            .setOption("Inspect")
            .setTarget(original.getTarget())
            .setType(MenuAction.RUNELITE)
            .setItemId(itemId)
            .onClick(entry -> itemInspector.open(inspectedItemId));
    }

    private void renderSlot(ItemComposition composition, SpinningItemsOverlay.HoveredSlot slot,
        SpinCategory category)
    {
        int originalPitch = composition.getXan2d();
        int originalYaw = composition.getYan2d();
        int originalRoll = composition.getZan2d();
        SpritePixels original = client.createItemSprite(slot.itemId, slot.quantity, 1,
            SpritePixels.DEFAULT_SHADOW_COLOR, quantityMode(slot), false, Constants.CLIENT_DEFAULT_ZOOM);
        if (original == null)
        {
            overlay.clearRenderedSlot();
            return;
        }

        SpritePixels spinning = null;
        try
        {
            applyRotation(composition, category, originalPitch, originalYaw, spinOffset);
            client.getItemSpriteCache().reset();
            spinning = client.createItemSprite(slot.itemId, slot.quantity, 1,
                SpritePixels.DEFAULT_SHADOW_COLOR, quantityMode(slot), false, Constants.CLIENT_DEFAULT_ZOOM);
        }
        finally
        {
            composition.setXan2d(originalPitch);
            composition.setYan2d(originalYaw);
            composition.setZan2d(originalRoll);
            client.getItemSpriteCache().reset();
        }

        if (spinning != null)
        {
            BufferedImage originalImage = original.toBufferedImage();
            BufferedImage spinningImage = spinning.toBufferedImage();
            overlay.setRenderedSlot(slot, originalImage, spinningImage);
        }
    }

    private void applyRotation(ItemComposition composition, SpinCategory category,
        int originalPitch, int originalYaw, int offset)
    {
        boolean equipment = category == SpinCategory.ARMOUR || category == SpinCategory.WEAPONS;
        if (!equipment || config.equipmentSpinStyle() == EquipmentSpinStyle.HORIZONTAL_TUMBLE)
        {
            composition.setYan2d(spunAngle(originalYaw, offset));
            return;
        }

        composition.setXan2d(spunAngle(originalPitch, offset));
        if (config.equipmentSpinStyle() == EquipmentSpinStyle.MIXED)
        {
            composition.setYan2d(spunAngle(originalYaw, offset / 2));
        }
    }

    private static int quantityMode(SpinningItemsOverlay.HoveredSlot slot)
    {
        if (slot.quantityMode == ItemQuantityMode.NEVER
            || slot.quantityMode == ItemQuantityMode.ALWAYS
            || slot.quantityMode == ItemQuantityMode.STACKABLE)
        {
            return slot.quantityMode;
        }
        return ItemQuantityMode.STACKABLE;
    }

    private boolean isEnabled(SpinCategory category)
    {
        switch (category)
        {
            case FOOD:
                return config.spinFood();
            case POTIONS:
                return config.spinPotions();
            case ARMOUR:
                return config.spinArmour();
            case WEAPONS:
                return config.spinWeapons();
            case TOOLS:
                return config.spinTools();
            default:
                return config.spinOther();
        }
    }

    private void clearActiveSlot()
    {
        activeSlot = null;
        spinOffset = 0;
        updateCounter = 0;
        overlay.clearRenderedSlot();
    }

    static SpinCategory classify(String[] actions, String name)
    {
        if (hasAction(actions, "Drink", "Sip"))
        {
            return SpinCategory.POTIONS;
        }
        if (hasAction(actions, "Eat", "Consume", "Bite", "Chew"))
        {
            return SpinCategory.FOOD;
        }
        if (hasAction(actions, "Wield"))
        {
            return SpinCategory.WEAPONS;
        }
        if (hasAction(actions, "Wear", "Equip"))
        {
            return SpinCategory.ARMOUR;
        }

        String lowerName = name == null ? "" : name.toLowerCase(Locale.ROOT);
        if (Arrays.stream(TOOL_WORDS).anyMatch(lowerName::contains))
        {
            return SpinCategory.TOOLS;
        }
        return SpinCategory.OTHER;
    }

    static boolean isNoted(int noteTemplateId)
    {
        return noteTemplateId != -1;
    }

    private static boolean hasAction(String[] actions, String... expected)
    {
        if (actions == null)
        {
            return false;
        }
        for (String action : actions)
        {
            if (action == null)
            {
                continue;
            }
            for (String value : expected)
            {
                if (value.equalsIgnoreCase(action))
                {
                    return true;
                }
            }
        }
        return false;
    }

    static int spunAngle(int original, int offset)
    {
        return (original + offset) & ANGLE_MASK;
    }
}

package com.spinningitems;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

@Singleton
final class ItemInspectOverlay extends Overlay
{
    private static final int MAX_PANEL_WIDTH = 360;
    private static final int MAX_PANEL_HEIGHT = 400;
    private final Client client;
    private final ItemInspectController controller;
    private BufferedImage cachedModelImage;
    private ItemInspectController.ModelSnapshot cachedModel;
    private int cachedPitch;
    private int cachedYaw;
    private int cachedRoll;
    private int cachedOrbitPitch;
    private int cachedOrbitYaw;
    private int cachedSize;
    private double cachedZoom;

    @Inject
    private ItemInspectOverlay(Client client, ItemInspectController controller)
    {
        this.client = client;
        this.controller = controller;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setPriority(OverlayPriority.HIGHEST);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!controller.isOpen())
        {
            cachedModelImage = null;
            cachedModel = null;
            return null;
        }
        int canvasWidth = client.getCanvasWidth();
        int canvasHeight = client.getCanvasHeight();
        if (canvasWidth <= 0 || canvasHeight <= 0) return null;
        int panelWidth = Math.min(MAX_PANEL_WIDTH, Math.max(260, canvasWidth - 36));
        int panelHeight = Math.min(MAX_PANEL_HEIGHT, Math.max(320, canvasHeight - 36));
        int panelX = (canvasWidth - panelWidth) / 2;
        int panelY = (canvasHeight - panelHeight) / 2;
        Rectangle panel = new Rectangle(panelX, panelY, panelWidth, panelHeight);
        controller.setPanelBounds(panel);

        graphics.setComposite(AlphaComposite.SrcOver);
        graphics.setColor(new Color(0, 0, 0, 188));
        graphics.fillRect(0, 0, canvasWidth, canvasHeight);
        graphics.setColor(new Color(18, 18, 20, 246));
        graphics.fillRoundRect(panelX, panelY, panelWidth, panelHeight, 18, 18);
        graphics.setStroke(new BasicStroke(2f));
        graphics.setColor(new Color(104, 84, 54, 230));
        graphics.drawRoundRect(panelX, panelY, panelWidth - 1, panelHeight - 1, 18, 18);

        List<String> statLines = controller.getStatLines();
        boolean hasStats = !statLines.isEmpty();
        drawItem(graphics, panel, hasStats);
        if (controller.isCelebration())
        {
            drawCelebration(graphics, panel);
        }
        int nameBaseline = hasStats ? panelY + 247 : panelY + panelHeight - 55;
        drawCenteredText(graphics, controller.getItemName(), new Font(Font.SANS_SERIF, Font.BOLD, 17),
            new Color(255, 152, 31), panelX + panelWidth / 2, nameBaseline);
        if (hasStats)
        {
            drawStats(graphics, statLines, panelX + panelWidth / 2, nameBaseline + 20, panelY + panelHeight - 42);
        }
        drawCenteredText(graphics, "Drag to rotate  •  Scroll to zoom  •  Esc to close",
            new Font(Font.SANS_SERIF, Font.PLAIN, 11), new Color(220, 220, 220),
            panelX + panelWidth / 2, panelY + panelHeight - 24);
        return new Dimension(canvasWidth, canvasHeight);
    }

    private void drawItem(Graphics2D graphics, Rectangle panel, boolean hasStats)
    {
        int availableWidth = panel.width - 42;
        int availableHeight = hasStats ? 220 : panel.height - 108;
        int size = Math.max(150, Math.min(availableWidth, availableHeight));
        int x = panel.x + (panel.width - size) / 2;
        int y = panel.y + 16 + Math.max(0, (availableHeight - size) / 2);
        graphics.setColor(new Color(7, 7, 9, 190));
        graphics.fillOval(x + size / 5, y + size - 38, size * 3 / 5, 35);

        ItemInspectController.ModelSnapshot model = controller.getModelSnapshot();
        if (model != null)
        {
            drawSmoothModel(graphics, model, x, y, size);
            return;
        }

        BufferedImage image = controller.getItemImage();
        if (image == null)
        {
            drawCenteredText(graphics, "Loading item…", new Font(Font.SANS_SERIF, Font.PLAIN, 16),
                Color.LIGHT_GRAY, panel.x + panel.width / 2, y + size / 2);
            return;
        }
        Object oldInterpolation = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
        graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
        graphics.drawImage(image, x, y, size, size, null);
        if (oldInterpolation != null) graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, oldInterpolation);
    }

    private static void drawStats(Graphics2D graphics, List<String> lines, int centerX, int startY, int bottomY)
    {
        Font font = new Font(Font.SANS_SERIF, Font.PLAIN, 10);
        int baseline = startY;
        for (String line : lines)
        {
            if (baseline > bottomY)
            {
                break;
            }
            drawCenteredText(graphics, line, font, new Color(205, 205, 205), centerX, baseline);
            baseline += 15;
        }
    }

    private void drawSmoothModel(Graphics2D graphics, ItemInspectController.ModelSnapshot model,
        int x, int y, int size)
    {
        int pitch = controller.getPitch();
        int yaw = controller.getYaw();
        int roll = controller.getRoll();
        int orbitPitch = controller.getOrbitPitch();
        int orbitYaw = controller.getOrbitYaw();
        double zoom = controller.getZoomScale();
        if (cachedModelImage == null || cachedModel != model || cachedPitch != pitch || cachedYaw != yaw
            || cachedRoll != roll || cachedOrbitPitch != orbitPitch || cachedOrbitYaw != orbitYaw
            || cachedSize != size || Double.compare(cachedZoom, zoom) != 0)
        {
            cachedModelImage = SmoothModelRenderer.render(model, size, pitch, yaw, roll,
                orbitPitch, orbitYaw, zoom);
            cachedModel = model;
            cachedPitch = pitch;
            cachedYaw = yaw;
            cachedRoll = roll;
            cachedOrbitPitch = orbitPitch;
            cachedOrbitYaw = orbitYaw;
            cachedSize = size;
            cachedZoom = zoom;
        }
        graphics.drawImage(cachedModelImage, x, y, null);
    }

    private static void drawCelebration(Graphics2D graphics, Rectangle panel)
    {
        long now = System.currentTimeMillis();
        double phase = now / 700.0;
        int centerX = panel.x + panel.width / 2;
        int centerY = panel.y + (panel.height - 100) / 2;
        int radiusX = panel.width / 2 - 28;
        int radiusY = (panel.height - 118) / 2;
        Object oldAntialiasing = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        for (int i = 0; i < 18; i++)
        {
            double angle = phase * (i % 2 == 0 ? 0.7 : -0.45) + i * Math.PI * 2.0 / 18.0;
            int sparkleX = centerX + (int) Math.round(Math.cos(angle) * radiusX);
            int sparkleY = centerY + (int) Math.round(Math.sin(angle) * radiusY);
            double pulse = 0.5 + 0.5 * Math.sin(phase * 4.0 + i * 1.7);
            int size = 3 + (int) Math.round(pulse * 6.0);
            int alpha = 100 + (int) Math.round(pulse * 155.0);
            Color color = i % 3 == 0 ? new Color(255, 246, 160, alpha)
                : i % 3 == 1 ? new Color(255, 184, 72, alpha)
                : new Color(225, 238, 255, alpha);
            graphics.setColor(color);
            int[] xs = {sparkleX, sparkleX + size / 3, sparkleX + size, sparkleX + size / 3,
                sparkleX, sparkleX - size / 3, sparkleX - size, sparkleX - size / 3};
            int[] ys = {sparkleY - size, sparkleY - size / 3, sparkleY, sparkleY + size / 3,
                sparkleY + size, sparkleY + size / 3, sparkleY, sparkleY - size / 3};
            graphics.fillPolygon(xs, ys, xs.length);
        }
        drawCenteredText(graphics, "NEW COLLECTION LOG ITEM!",
            new Font(Font.SANS_SERIF, Font.BOLD, 13), new Color(255, 218, 96),
            centerX, panel.y + 25);
        if (oldAntialiasing != null)
        {
            graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, oldAntialiasing);
        }
    }

    private static void drawCenteredText(Graphics2D graphics, String text, Font font,
        Color color, int centerX, int baselineY)
    {
        String safeText = text == null ? "" : text;
        graphics.setFont(font);
        FontMetrics metrics = graphics.getFontMetrics();
        int x = centerX - metrics.stringWidth(safeText) / 2;
        graphics.setColor(new Color(0, 0, 0, 210));
        graphics.drawString(safeText, x + 1, baselineY + 1);
        graphics.setColor(color);
        graphics.drawString(safeText, x, baselineY);
    }
}

package com.spinningitems;

import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

@Singleton
final class CollectionLogInspectManager
{
    private static final String PREFIX = "New item added to your collection log: ";
    private static final String CLICK_HINT = " (click to inspect)";
    private static final int DEFINITIONS_PER_TICK = 250;
    private static final int MAX_CLICKABLE_MESSAGES = 24;

    private final Client client;
    private final ItemInspectController inspector;
    private final Map<String, Integer> itemIdsByName = new HashMap<>();
    private final Map<MessageNode, String> pendingMessages = new LinkedHashMap<>();
    private final Map<String, Integer> clickableItems = new LinkedHashMap<String, Integer>()
    {
        @Override
        protected boolean removeEldestEntry(Map.Entry<String, Integer> eldest)
        {
            return size() > MAX_CLICKABLE_MESSAGES;
        }
    };
    private int nextItemId;
    private boolean indexComplete;

    @Inject
    private CollectionLogInspectManager(Client client, ItemInspectController inspector)
    {
        this.client = client;
        this.inspector = inspector;
    }

    void onChatMessage(ChatMessage event)
    {
        String itemName = parseCollectionItem(event.getMessage());
        if (itemName == null || itemName.isEmpty() || event.getMessageNode() == null)
        {
            return;
        }

        Integer cachedId = itemIdsByName.get(normalize(itemName));
        if (cachedId != null)
        {
            makeClickable(event.getMessageNode(), itemName, cachedId);
            return;
        }
        pendingMessages.put(event.getMessageNode(), itemName);
    }

    void update()
    {
        if (!pendingMessages.isEmpty() && !indexComplete)
        {
            indexMoreItems();
        }
        resolvePendingMessages();
        bindVisibleChatLines();
    }

    void reset()
    {
        pendingMessages.clear();
        clickableItems.clear();
    }

    private void indexMoreItems()
    {
        int end = Math.min(client.getItemCount(), nextItemId + DEFINITIONS_PER_TICK);
        for (; nextItemId < end; nextItemId++)
        {
            ItemComposition composition = client.getItemDefinition(nextItemId);
            if (composition == null || composition.getName() == null || "null".equalsIgnoreCase(composition.getName()))
            {
                continue;
            }
            String key = normalize(composition.getName());
            Integer existing = itemIdsByName.get(key);
            if (existing == null || isBetterDefinition(composition, client.getItemDefinition(existing)))
            {
                itemIdsByName.put(key, nextItemId);
            }
        }
        indexComplete = nextItemId >= client.getItemCount();
    }

    private static boolean isBetterDefinition(ItemComposition candidate, ItemComposition current)
    {
        if (current == null)
        {
            return true;
        }
        boolean candidateNormal = candidate.getNote() == -1 && candidate.getPlaceholderTemplateId() == -1;
        boolean currentNormal = current.getNote() == -1 && current.getPlaceholderTemplateId() == -1;
        return candidateNormal && !currentNormal;
    }

    private void resolvePendingMessages()
    {
        Iterator<Map.Entry<MessageNode, String>> iterator = pendingMessages.entrySet().iterator();
        while (iterator.hasNext())
        {
            Map.Entry<MessageNode, String> entry = iterator.next();
            Integer itemId = itemIdsByName.get(normalize(entry.getValue()));
            if (itemId != null)
            {
                makeClickable(entry.getKey(), entry.getValue(), itemId);
                iterator.remove();
            }
            else if (indexComplete)
            {
                iterator.remove();
            }
        }
    }

    private void makeClickable(MessageNode node, String itemName, int itemId)
    {
        String formatted = PREFIX + "<col=ffb83e><u>" + itemName + "</u></col>"
            + "<col=9fdf9f>" + CLICK_HINT + "</col>";
        node.setRuneLiteFormatMessage(formatted);
        clickableItems.put(normalize(itemName), itemId);
        client.refreshChat();
    }

    private void bindVisibleChatLines()
    {
        if (clickableItems.isEmpty())
        {
            return;
        }
        Widget scrollArea = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
        if (scrollArea == null || scrollArea.getDynamicChildren() == null)
        {
            return;
        }
        for (Widget widget : scrollArea.getDynamicChildren())
        {
            if (widget == null || widget.getText() == null)
            {
                continue;
            }
            String itemName = parseCollectionItem(widget.getText());
            if (itemName == null)
            {
                continue;
            }
            itemName = itemName.replace(CLICK_HINT, "").trim();
            Integer itemId = clickableItems.get(normalize(itemName));
            if (itemId == null || hasInspectAction(widget))
            {
                continue;
            }
            final int inspectedItemId = itemId;
            widget.setAction(0, "Inspect");
            widget.setOnOpListener((JavaScriptCallback) event -> inspector.open(inspectedItemId, true));
        }
    }

    private static boolean hasInspectAction(Widget widget)
    {
        String[] actions = widget.getActions();
        if (actions == null)
        {
            return false;
        }
        for (String action : actions)
        {
            if ("Inspect".equals(action))
            {
                return true;
            }
        }
        return false;
    }

    static String parseCollectionItem(String message)
    {
        if (message == null)
        {
            return null;
        }
        String plain = Text.removeTags(message).replace('\u00A0', ' ').trim();
        return plain.startsWith(PREFIX) ? plain.substring(PREFIX.length()).trim() : null;
    }

    private static String normalize(String value)
    {
        return value.toLowerCase(java.util.Locale.ROOT).trim();
    }
}

